from pathlib import Path
import json,html,wave
p=Path(__file__).parent
receipt=json.loads((p/'../../proof/reference-parity/native-lifecycle.json').read_text())
e=lambda s:html.escape(s)
scenes=[('intro',17,'Working application · recorded local interaction','Memory that shows its sources.'),('graph',26,'Real Codex answer · synthetic OrbitWorks documents','Follow the approval path.'),('memory',27,'Recorded native Codex evidence · 18 October 2026','A later session remembers.'),('method',25,'Controlled pilot · exact inputs and provider traces','Two models. Two methods.'),('results',35,'Measured results · approval question, three valid repeats','Less context. Faster answers in this pilot.'),('close',34,'Graph Hacks · solo submission · Tracks 02 + 03','Run it. Inspect it. Reproduce it.')]
css='''*{box-sizing:border-box}html,body{margin:0;width:1920px;height:1080px;overflow:hidden;background:#f5f4ef;color:#25362e;font-family:system-ui,sans-serif}.clip{position:absolute;inset:0;width:1920px;height:1080px}.paper{padding:74px 92px;background:#f5f4ef}.kicker{font-size:22px;letter-spacing:3px;text-transform:uppercase;color:#3f6249;font-weight:650;margin:0 0 18px}h1{font-family:ui-serif,Georgia,serif;font-size:68px;letter-spacing:-2px;font-weight:500;margin:0 0 40px;line-height:1.1}h2{font-size:32px;line-height:1.25;margin:0 0 18px}.card{padding:32px 36px;border:1px solid #b9c7bb;border-radius:18px;background:#fffef9}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.small{font-size:23px;line-height:1.5;color:#43584a}.quote{font-family:ui-serif,Georgia,serif;font-size:33px;line-height:1.42;margin:0}footer{position:absolute;bottom:38px;left:92px;right:92px;display:flex;justify-content:space-between;font-size:20px;color:#43584a}.pill{display:inline-block;background:#e3ebdf;border-radius:30px;padding:9px 18px;font-size:22px;font-weight:600}table{border-collapse:collapse;width:100%;font-size:28px}th,td{text-align:left;border-bottom:1px solid #bdcabe;padding:22px 18px}th{font-size:22px;text-transform:uppercase;letter-spacing:1px;background:#e8eee3}.num{font-variant-numeric:tabular-nums}.flow{display:flex;align-items:center;gap:16px;font-size:25px;margin:28px 0}.step{flex:1;background:#e6eddf;padding:22px;border-radius:12px;text-align:center}.hero{font-size:74px;font-weight:650;line-height:1.1;margin:18px 0;color:#31533c}.mono{font-family:ui-monospace,monospace;font-size:25px;line-height:1.6;white-space:pre-wrap}.appframe{position:absolute;left:50px;top:210px;width:1820px;height:810px;overflow:hidden;border:1px solid #aebfaf;border-radius:14px}.appframe video{width:1820px;height:810px;object-fit:contain;position:absolute;top:0px}.top{position:absolute;left:70px;top:34px;right:70px}.top h1{font-size:56px;margin-bottom:12px}.top .kicker{font-size:18px}.videofoot{position:absolute;top:165px;left:72px;font-size:23px;color:#43584a}.note{margin-top:22px;font-size:23px;line-height:1.5}.accent{color:#31533c}.failure{border-left:6px solid #b16535;padding-left:22px}.checks{display:grid;grid-template-columns:1fr 1fr;gap:20px}.checks div{padding:24px;background:#e5eddf;border-radius:12px;font-size:25px}'''
content={
'intro':'''<div class="top"><p class="kicker">Working application · real browser recording</p><h1>Memory that shows its sources.</h1></div><div class="videofoot">Codex + FalkorDB · question, answer, relationships, quotations</div><div class="appframe"><video id="demo-intro" class="clip" data-start="0" data-duration="17" src="assets/demo-intro.mp4" muted playsinline></video></div>''',
'graph':'''<div class="top"><p class="kicker">Live result · recording continues at normal speed</p><h1>Policy → role → holder → delegate</h1></div><div class="videofoot">£900 exceeds £750 · 15 Oct is inside the 1–31 Oct delegation · Mira Shah [S6, S8, S10]</div><div class="appframe"><video id="demo-graph" class="clip" data-start="0" data-duration="26" src="assets/demo-graph.mp4" muted playsinline></video></div>''',
'memory':f'''<p class="kicker">Recorded native Codex evidence · not a staged terminal</p><h1>A later session remembers.</h1><div class="grid"><div class="card"><span class="pill">Session A · 15:12:54 UTC</span><h2 style="margin-top:28px">A new decision</h2><p class="quote">“{e(receipt['source'])}”</p><p class="small">Codex replied: “Recorded.”<br>Actual SessionEnd hook captured the filtered transcript.</p></div><div class="card"><span class="pill">Separate Session B · 15:13:35 UTC</span><h2 style="margin-top:28px">Source-cited recall</h2><p class="quote">{e(receipt['answer'].replace('**',''))}</p></div></div><div class="flow"><div class="step">Capture</div>→<div class="step">Summarize + distil</div>→<div class="step">Extract facts</div>→<div class="step">Publish FalkorDB</div>→<div class="step">Recall</div></div><p class="small">Detached worker · real provider calls · immutable snapshot · original receipt in proof/reference-parity/native-lifecycle.json</p>''',
'method':'''<p class="kicker">Controlled retrieval pilot · 32 provider attempts</p><h1>Two models. Two methods.</h1><div class="grid"><div class="card"><h2>Without graph</h2><p class="hero">Search + read</p><p class="small">Real local rg and file reads.<br>The model chooses and executes retrieval.<br>Raw tool traces record what actually ran.</p></div><div class="card"><h2>With graph</h2><p class="hero">Graph-only recall</p><p class="small">Native FalkorDB multi-hop context.<br>No BM25, embeddings or distilled-note hits.<br>Model receives source-backed evidence.</p></div></div><div class="card" style="margin-top:28px"><h2>Same 16 synthetic source documents · 6 questions</h2><p class="small">Sol and Luna each run both methods. Approval case repeated 3 times per arm; 8 attempts per cell. Matched low reasoning settings; alternating method order within each model. Prompts, corpus, frozen implementation, traces and provider usage are published.</p></div>''',
'results':'''<p class="kicker">Approval-repeat medians · provider-reported input includes cached tokens</p><h1>Less context. Faster answers in this pilot.</h1><table class="num"><thead><tr><th>Model / method</th><th>Time</th><th>Input tokens</th><th>Valid repeats</th><th>Strict checks</th></tr></thead><tbody><tr><td>Sol · local search</td><td>13.15 s</td><td>52,729</td><td>3 / 3</td><td>8 / 8</td></tr><tr><td>Sol · graph</td><td>6.70 s</td><td>16,764</td><td>3 / 3</td><td>8 / 8</td></tr><tr><td>Luna · local search</td><td>9.92 s</td><td>50,383</td><td>2 / 3</td><td>5 / 8</td></tr><tr style="background:#e3ebdf"><td>Luna · graph</td><td>5.89 s</td><td>15,713</td><td>3 / 3</td><td>7 / 8</td></tr></tbody></table><div class="grid" style="margin-top:24px"><div><h2>Sol search → Luna graph</h2><p class="hero" style="font-size:52px">2.23× faster · 70.2% fewer input tokens</p><p class="small">Both 3 / 3 correct on the approval repeats.</p></div><div class="failure"><h2>Failures remain visible</h2><p class="small">3 Luna baselines skipped required retrieval.<br>1 Luna graph answer said “A Support Agent”; exact-label grading failed.<br>Cache, network/service load and model order affect timing. Write-time costs excluded. Small synthetic pilot; no universal model claim.</p></div></div>''',
'close':'''<p class="kicker">Graph Hacks · solo · Agent Memory and Coordination + Company Brain</p><h1>Run it. Inspect it. Reproduce it.</h1><div class="grid"><div class="card"><h2>Complete local setup</h2><pre class="mono">docker compose -p graph-memory-lab \\<br>  up -d --wait<br>uv sync --python 3.12<br>uv run python -m memory_lab</pre><p class="small">Evidence mode needs no model account.<br>Codex answers use your authenticated local CLI.<br>FalkorDB is the central context database.</p></div><div class="checks"><div><strong>123</strong> tests passed</div><div><strong>5 / 5</strong> original graph cases</div><div><strong>4 / 4</strong> original RAG checks</div><div><strong>Native sessions</strong><br>capture → worker → later recall</div><div><strong>Database recreation</strong><br>persistent data verified</div><div><strong>Raw proof</strong><br>all attempts, including failures</div></div></div><p class="note">github.com/VasuBansal7576/memory-lab-falkordb</p><p class="small">Independent implementation inspired by Glitch Cat Club’s graph-memory-starter (MIT). Substantial Codex assistance disclosed. Synthetic data; local prototype. No production multi-tenant authorization or autonomous external actions claimed.</p>'''
}
(p/'compositions').mkdir(exist_ok=True)
root=[];offset=0
for i,(sid,dur,k,title) in enumerate(scenes):
 inner=f'<div id="{sid}" data-composition-id="{sid}" data-width="1920" data-height="1080" >{content[sid]}<footer><span>Memory Lab / FalkorDB + Codex</span><span>{i+1:02} / 06</span></footer></div>'
 # The filmed interface is intentionally left unanimated; evidence cards enter gently.
 anim='' if sid in ('intro','graph') else f'tl.fromTo("#{sid} h1",{{opacity:0,y:12}},{{opacity:1,y:0,duration:.45,ease:"power2.out"}},0);'
 (p/'compositions'/f'{sid}.html').write_text(f'<!doctype html><html><body><template><style>{css}#{sid}{{position:absolute;inset:0;padding:74px 92px;background:#f5f4ef}}</style>{inner}<script>{{const tl=gsap.timeline({{paused:true}});{anim}window.__timelines["{sid}"]=tl;}}</script></template></body></html>')
 root.append(f'<div id="slot-{sid}" class="clip" data-composition-id="{sid}" data-composition-src="compositions/{sid}.html" data-start="{offset}" data-duration="{dur}" data-track-index="0" data-width="1920" data-height="1080"></div>')
 audio=json.loads((p/'narration.json').read_text())[i]['id']
 with wave.open(str(p/'assets'/f'{audio}.wav')) as wav: audio_duration=wav.getnframes()/wav.getframerate()
 root.append(f'<audio id="voice-{sid}" src="assets/{audio}.wav" data-start="{offset+.6}" data-duration="{audio_duration}" data-track-index="1"></audio>')
 offset+=dur
(p/'index.html').write_text(f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=1920,height=1080"><script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script><style>{css}#main{{position:relative;width:1920px;height:1080px}}</style></head><body><div id="main" data-composition-id="main" data-start="0" data-duration="{offset}" data-width="1920" data-height="1080">'+''.join(root)+'</div><script>window.__timelines=window.__timelines||{};window.__timelines.main=gsap.timeline({paused:true});</script></body></html>')
(p/'STORYBOARD.md').write_text('# Evidence demo\n\nSix scenes; real application capture first, immutable native receipt second, then benchmark methods/results and setup.\n\n'+'\n'.join(f'{i+1}. {sid}: {d}s — {title}' for i,(sid,d,k,title) in enumerate(scenes))+'\n\nTransitions are direct cuts; only headings fade gently. No fake live terminal or benchmark reenactment. Voice: local Kokoro am_adam; no music.\n')
(p/'design.md').write_text('# Visual direction\n\nWarm paper #f5f4ef, ink #25362e, forest #31533c. System serif headings and system sans body. Six evidence scenes, direct cuts, gentle heading entrances. Real local screen recording, exact receipt quotations, complete benchmark table including failures. 1920×1080; duration164s.\n')
print(offset)
